use crate::db::DatabaseManager;
use std::env;
use std::fs;
use std::path::Path;

pub fn run(score: Option<i64>) {
    let paths: Vec<String> = env::args().skip(2).collect();

    if paths.is_empty() {
        eprintln!("zoxide: missing path");
        std::process::exit(1);
    }

    let db = match DatabaseManager::new() {
        Ok(db) => db,
        Err(e) => {
            eprintln!("zoxide: could not open database: {}", e);
            std::process::exit(1);
        }
    };

    for path in &paths {
        let path = Path::new(path);

        if !path.exists() {
            eprintln!("zoxide: {} does not exist", path.display());
            std::process::exit(1);
        }

        if !path.is_dir() {
            eprintln!("zoxide: {} is not a directory", path.display());
            std::process::exit(1);
        }

        let score = score.unwrap_or(1.0);

        if let Err(e) = db.increment(path.to_str().unwrap(), score) {
            eprintln!("zoxide: could not add directory: {}", e);
            std::process::exit(1);
        }
    }
}
