use crate::db::DatabaseManager;
use std::env;
use std::fs;
use std::path::Path;

pub fn run(from: ImportFrom, path: String, merge: bool) {
    let db = match DatabaseManager::new() {
        Ok(db) => db,
        Err(e) => {
            eprintln!("zoxide: could not open database: {}", e);
            std::process::exit(1);
        }
    };

    let source_path = Path::new(&path);

    if !source_path.exists() {
        eprintln!("zoxide: could not open database for importing: {}", path);
        eprintln!("Caused by:");
        eprintln!("    No such file or directory (os error 2)");
        std::process::exit(1);
    }

    if !source_path.is_file() {
        eprintln!("zoxide: could not open database for importing: {}", path);
        eprintln!("Caused by:");
        eprintln!("    Is a directory (os error 21)");
        std::process::exit(1);
    }

    let mut source_db = match DatabaseManager::new() {
        Ok(db) => db,
        Err(e) => {
            eprintln!("zoxide: could not open database for importing: {}", e);
            std::process::exit(1);
        }
    };

    // For now, just copy the source database
    let contents = match fs::read_to_string(&source_path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("zoxide: could not open database for importing: {}", e);
            std::process::exit(1);
        }
    };

    let source_entries: serde_json::Value = match serde_json::from_str(&contents) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("zoxide: could not parse source database: {}", e);
            std::process::exit(1);
        }
    };

    let mut target_db = match db.load() {
        Ok(d) => d,
        Err(e) => {
            eprintln!("zoxide: could not open database: {}", e);
            std::process::exit(1);
        }
    };

    if let Some(entries) = source_entries.as_object() {
        for (path, entry) in entries {
            if let Some(score) = entry.as_f64() {
                target_db.entries.insert(path.clone(), crate::db::Entry {
                    path: path.clone(),
                    score,
                    age: 0,
                });
            }
        }
    }

    if !merge {
        target_db.entries.clear();
    }

    if let Err(e) = db.save(&target_db) {
        eprintln!("zoxide: could not save database: {}", e);
        std::process::exit(1);
    }
}
