use crate::db::DatabaseManager;
use std::env;
use std::process;

pub fn run(
    all: bool,
    interactive: bool,
    list: bool,
    score: bool,
    exclude: Option<String>,
    base_dir: Option<String>,
    keywords: Vec<String>,
) {
    let db = match DatabaseManager::new() {
        Ok(db) => db,
        Err(e) => {
            eprintln!("zoxide: could not open database: {}", e);
            process::exit(1);
        }
    };

    let results = match db.query(&keywords, all) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("zoxide: could not query database: {}", e);
            process::exit(1);
        }
    };

    if results.is_empty() {
        eprintln!("zoxide: no match found");
        process::exit(1);
    }

    if interactive {
        if let Err(e) = db.query_interactive(&keywords, all, &exclude, &base_dir) {
            eprintln!("zoxide: could not query database: {}", e);
            process::exit(1);
        }
    } else if list {
        for (path, _) in &results {
            println!("{}", path);
        }
    } else if score {
        for (path, s) in &results {
            println!("   {:>6.1} {}", s, path);
        }
    } else {
        for (path, _) in &results {
            println!("{}", path);
        }
    }
}
EOF"}

