#[command(author = "Ajeet D'Souza <98ajeet@gmail.com>")]
#[command(version = "0.9.9")]
#[command(about = "A smarter cd command for your terminal", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    #[arg(short, long, action = clap::ArgAction::Help)]
    help: Option<bool>,

    #[arg(short = 'V', long, action = clap::ArgAction::Help)]
    version: Option<bool>,
}

#[derive(Subcommand)]
enum Commands {
    /// Add a new directory or increment its rank
    Add {
        /// The rank to increment the entry if it exists or initialize it with if it doesn't
        #[arg(short = 's', long)]
        score: Option<i64>,
    },
    /// Edit the database
    Edit,
    /// Import entries from another application
    Import {
        /// Application to import from
        #[arg(long, value_enum)]
        from: ImportFrom,

        /// Path to the database
        path: String,

        /// Merge into existing database
        #[arg(long)]
        merge: bool,
    },
    /// Generate shell configuration
    Init {
        /// Shell to initialize for
        #[arg(value_enum)]
        shell: Shell,

        /// Prevents zoxide from defining the `z` and `zi` commands
        #[arg(long)]
        no_cmd: bool,

        /// Changes the prefix of the `z` and `zi` commands
        #[arg(long, default_value = "z")]
        cmd: String,

        /// Changes how often zoxide increments a directory's score
        #[arg(long, default_value = "pwd", value_enum)]
        hook: Hook,
    },
    /// Search for a directory in the database
    Query {
        /// Show unavailable directories
        #[arg(short = 'a', long)]
        all: bool,

        /// Use interactive selection
        #[arg(short = 'i', long)]
        interactive: bool,

        /// List all matching directories
        #[arg(short = 'l', long)]
        list: bool,

        /// Print score with results
        #[arg(short = 's', long)]
        score: bool,

        /// Exclude the current directory
        #[arg(long)]
        exclude: Option<String>,

        /// Only search within this directory
        #[arg(long)]
        base_dir: Option<String>,

        /// Keywords to search for
        keywords: Vec<String>,
    },
    /// Remove a directory from the database
    Remove {
        /// Paths to remove
        paths: Vec<String>,
    },
}

#[derive(clap::ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
enum ImportFrom {
    Autojump,
    Z,
}

#[derive(clap::ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
enum Shell {
    Bash,
    Elvish,
    Fish,
    Nushell,
    Posix,
    Powershell,
    Tcsh,
    Xonsh,
    Zsh,
}

#[derive(clap::ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
enum Hook {
    None,
    Prompt,
    Pwd,
}

fn main() {
    let cli = Cli::parse();

    if let Some(true) = cli.help {
        println!("{}", Cli::command().render_help());
        std::process::exit(0);
    }

    if let Some(true) = cli.version {
        println!("zoxide 0.9.9");
        std::process::exit(0);
    }

    match cli.command {
        Some(Commands::Add { score }) => {
            add::run(score);
        }
        Some(Commands::Edit) => {
            edit::run();
        }
        Some(Commands::Import { from, path, merge }) => {
            import::run(from, path, merge);
        }
        Some(Commands::Init { shell, no_cmd, cmd, hook }) => {
            init::run(shell, no_cmd, cmd, hook);
        }
        Some(Commands::Query {
            all,
            interactive,
            list,
            score,
            exclude,
            base_dir,
            keywords,
        }) => {
            query::run(all, interactive, list, score, exclude, base_dir, keywords);
        }
        Some(Commands::Remove { paths }) => {
            remove::run(paths);
        }
        None => {
            println!("{}", Cli::command().render_help());
            std::process::exit(0);
        }
    }
}
