use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::env;
use std::fs::{self, File};
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::sync::Mutex;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Entry {
    path: String,
    score: f64,
    age: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Database {
    entries: BTreeMap<String, Entry>,
}

pub struct DatabaseManager {
    data_dir: PathBuf,
    db_path: PathBuf,
}

impl DatabaseManager {
    pub fn new() -> io::Result<Self> {
        let data_dir = dirs::data_local_dir()
            .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "Could not determine data directory"))?
            .join("zoxide");

        fs::create_dir_all(&data_dir)?;

        let db_path = data_dir.join("db.zo");

        Ok(Self { data_dir, db_path })
    }

    pub fn load(&self) -> io::Result<Database> {
        if !self.db_path.exists() {
            return Ok(Database {
                entries: BTreeMap::new(),
            });
        }

        let mut file = File::open(&self.db_path)?;
        let mut contents = String::new();
        file.read_to_string(&mut contents)?;

        let db: Database = serde_json::from_str(&contents)
            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e));

        Ok(db)
    }

    pub fn add(&self, path: &str, score: f64) -> io::Result<()> {
        let mut db = self.load()?;

        let entry = Entry {
            path: path.to_string(),
            score,
            age: 0,
        };

        db.entries.insert(path.to_string(), entry);
        self.save(&db)
    }

    pub fn increment(&self, path: &str, score: f64) -> io::Result<()> {
        let mut db = self.load()?;

        if let Some(entry) = db.entries.get_mut(path) {
            entry.score = score;
        } else {
            let entry = Entry {
                path: path.to_string(),
                score,
                age: 0,
            };
            db.entries.insert(path.to_string(), entry);
        }

        self.save(&db)
    }

    pub fn remove(&self, path: &str) -> io::Result<()> {
        let mut db = self.load()?;
        db.entries.remove(path);
        self.save(&db)
    }

    pub fn query(&self, keywords: &[String], all: bool) -> io::Result<Vec<(String, f64)>> {
        let db = self.load()?;

        let mut results = Vec::new();

        for (path, entry) in db.entries.iter() {
            if !all && path == env::current_dir()?.to_str().unwrap_or("") {
                continue;
            }

            let path_lower = path.to_lowercase();
            let mut matched = false;

            for keyword in keywords {
                let keyword_lower = keyword.to_lowercase();
                if path_lower.contains(&keyword_lower) {
                    matched = true;
                    break;
                }
            }

            if matched {
                results.push((path.clone(), entry.score));
            }
        }

        results.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        Ok(results)
    }
}
