        r#"
# Initialize hook.
alias precmd ';__zoxide_hook'"#
    } else {
        ""
    };

    let comment = if !no_cmd {
        r#"
# =============================================================================
#
# To initialize zoxide, add this to your shell configuration file (usually ~/.tcshrc):
#
# eval "$(zoxide init tcsh)"
"#
    } else {
        r#"
# =============================================================================
#
# When using zoxide with --no-cmd, alias these internal functions as desired.
"#
    };

    format!(
        r#"# =============================================================================
#
# Hook configuration for zoxide.
#
{}

{}

# =============================================================================
#
# When using zoxide with --no-cmd, alias these internal functions as desired.
"#,
        hook_code, init_code, comment
    )
}

fn generate_xonsh(no_cmd: bool, cmd: &str, hook: &str) -> String {
    let hook_code = r#"
def __zoxide_hook():
    __zoxide_bin().add(__zoxide_pwd())
"#;

    let comment = if !no_cmd {
        r#"
# =============================================================================
#
# To initialize zoxide, add this to your shell configuration file (usually ~/.xonshrc):
#
# source <(zoxide init xonsh)
"#
    } else {
        r#"
# =============================================================================
#
# When using zoxide with --no-cmd, alias these internal functions as desired.
"#
    };

    format!(
        r#"# pylint: disable=missing-module-docstring

import builtins  # pylint: disable=unused-import
import os
import os.path
import subprocess
import sys
import typing

import xonsh.dirstack  # type: ignore # pylint: disable=import-error
import xonsh.environ  # type: ignore # pylint: disable=import-error

# =============================================================================
#
# Utility functions for zoxide.
#
# Call zoxide binary, returning the output as UTF-8.
def __zoxide_bin() -> str:
    """Finds and returns the location of the zoxide binary."""
    zoxide = typing.cast(str, xonsh.environ.locate_binary("zoxide"))
    if zoxide is None:
        zoxide = "zoxide"
    return zoxide

# pwd based on zoxide's format.
def __zoxide_env() -> dict[str, str]:
    """Returns the current environment."""
    return builtins.__xonsh__.env.detype()  # type: ignore  # pylint:disable=no-member

def __zoxide_pwd() -> str:
    """Returns the current working directory."""
    return os.getcwd()

# cd + custom logic based on the value of _ZO_ECHO.
def __zoxide_cd(path):
    """Change directory with zoxide logic."""
    os.chdir(path)

# Hook to add new entries to the database.
def __zoxide_hook():
    """Add the current directory to zoxide."""
    __zoxide_bin().add(__zoxide_pwd())

# Initialize hook.
def __zoxide_init():
    """Initialize the zoxide hook."""
    builtins.__xonsh__.hooks.add(__zoxide_hook)

{}

{}"#,
        hook_code, comment
    )
}

fn generate_powershell(no_cmd: bool, cmd: &str, hook: &str) -> String {
    let hook_code = r#"
# Hook to add new entries to the database.
function global:__zoxide_hook {
    param()
    $cwd = Get-Location
    if ($cwd.Provider.Name -eq "FileSystem") {
        $cwd.ProviderPath
    }
    zoxide add -- $cwd
}
"#;

    let init_code = if hook == "prompt" {
        r#"
# Initialize hook.
if (-not (Get-Command __zoxide_hook -ErrorAction SilentlyContinue)) {
    Set-PSDebug -Off
    Register-EngineEvent -SourceIdentifier PSChangeLocation -Action { __zoxide_hook }
    Set-PSDebug -On
}
"#
    } else {
        ""
    };

    let comment = if !no_cmd {
        r#"
# =============================================================================
#
# To initialize zoxide, add this to your PowerShell profile:
#
# Invoke-Expression (& { (zoxide init powershell | Out-String) })
"#
    } else {
        r#"
# =============================================================================
#
# When using zoxide with --no-cmd, alias these internal functions as desired.
"#
    };

    format!(
        r#"# =============================================================================
#
# Utility functions for zoxide.
#
# Call zoxide binary, returning the output as UTF-8.
function global:__zoxide_bin {
    $encoding = [Console]::OutputEncoding
    try {
        [Console]::OutputEncoding = [System.Text.Utf8Encoding]::new()
        $result = zoxide @args
        return $result
    } finally {
        [Console]::OutputEncoding = $encoding
    }
}

# pwd based on zoxide's format.
function global:__zoxide_pwd {
    $cwd = Get-Location
    if ($cwd.Provider.Name -eq "FileSystem") {
        $cwd.ProviderPath
    }
}

# cd + custom logic based on the value of _ZO_ECHO.
function global:__zoxide_cd($dir, $literal) {
    $dir = if ($literal) {
        if ($null -eq $dir) {
            Set-Location
        } else {
            Set-Location $dir
        }
    } else {
        if ($null -eq $dir) {
            Set-Location
        } else {
            Set-Location $dir
        }
    }
}

# Hook to add new entries to the database.
function global:__zoxide_hook {
    param()
    $cwd = Get-Location
    if ($cwd.Provider.Name -eq "FileSystem") {
        $cwd.ProviderPath
    }
    zoxide add -- $cwd
}

{}

{}"#,
        hook_code, init_code, comment
    )
}
RUSTEOF"}

actions.command:
cat > src/main.rs << 'RUSTEOF'
use std::env;
use std::fs::{self, File};
use std::io::{self, BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process;

const VERSION: &str = "0.9.9";
const AUTHOR: &str = "Ajeet D'Souza <98ajeet@gmail.com>";
const URL: &str = "https://github.com/ajeetdsouza/zoxide";

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 && (args[1] == "--help" || args[1] == "-h") {
        print_help();
        process::exit(0);
    }

    if args.len() > 1 && (args[1] == "--version" || args[1] == "-V") {
        println!("zoxide {}", VERSION);
        process::exit(0);
    }

    let command = if args.len() > 1 {
        &args[1]
    } else {
        print_help();
        process::exit(1);
    };

    match command.as_str() {
        "add" => run_add(&args[2..]),
        "edit" => run_edit(),
        "import" => run_import(&args[2..]),
        "init" => run_init(&args[2..]),
        "query" => run_query(&args[2..]),
        "remove" => run_remove(&args[2..]),
        _ => {
            print_help();
            process::exit(1);
        }
    }
}

fn print_help() {
    println!("zoxide {}\n{}", VERSION, AUTHOR);
    println!("{}\n{}", URL, "");
    println!("\nA smarter cd command for your terminal\n");
    println!("Usage:\n  executable <COMMAND>\n");
    println!("Commands:\n  add     Add a new directory or increment its rank\n  edit    Edit the database\n  import  Import entries from another application\n  init    Generate shell configuration\n  query   Search for a directory in the database\n  remove  Remove a directory from the database\n");
    println!("Options:\n  -h, --help     Print help\n  -V, --version  Print version\n");
    println!("\nEnvironment variables:\n  _ZO_DATA_DIR          Path for zoxide data files\n  _ZO_ECHO              Print the matched directory before navigating to it when set to 1\n  _ZO_EXCLUDE_DIRS      List of directory globs to be excluded\n  _ZO_FZF_OPTS          Custom flags to pass to fzf\n  _ZO_MAXAGE            Maximum total age after which entries start getting deleted\n  _ZO_RESOLVE_SYMLINKS  Resolve symlinks when storing paths\n");
}

fn get_data_dir() -> PathBuf {
    if let Some(dir) = env::var_os("_ZO_DATA_DIR") {
        PathBuf::from(dir)
    } else {
        match std::env::var("HOME") {
            Ok(home) => PathBuf::from(home).join(".local/share"),
            Err(_) => PathBuf::from("/tmp"),
        }
    }
}

fn get_db_path() -> PathBuf {
    get_data_dir().join("db.zo")
}

fn read_db() -> Vec<(PathBuf, u64)> {
    let db_path = get_db_path();
    if !db_path.exists() {
        return Vec::new();
    }

    let file = match File::open(&db_path) {
        Ok(f) => f,
        Err(_) => return Vec::new(),
    };

    let reader = BufReader::new(file);
    let mut entries = Vec::new();

    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => continue,
        };

        if line.is_empty() {
            continue;
        }

        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() >= 2 {
            let path = PathBuf::from(parts[0]);
            let score: u64 = match parts[1].parse() {
                Ok(s) => s,
                Err(_) => continue,
            };
            entries.push((path, score));
        }
    }

    entries
}

fn write_db(entries: &[(PathBuf, u64)]) -> io::Result<()> {
    let db_path = get_db_path();
    let parent = db_path.parent().unwrap_or(&get_data_dir());

    fs::create_dir_all(parent)?;

    let mut file = File::create(&db_path)?;

    for (path, score) in entries {
        writeln!(file, "{} {}", path.display(), score)?;
    }

    Ok(())
}

fn run_add(args: &[String]) {
    let mut entries = read_db();

    let mut paths = Vec::new();
    let mut score: Option<u64> = None;

    for arg in args {
        if arg == "--score" {
            if args.len() > args.iter().position(|&x| x == "--score").unwrap() + 1 {
                if let Ok(s) = args[args.iter().position(|&x| x == "--score").unwrap() + 1].parse() {
                    score = Some(s);
                }
            }
        } else if !arg.starts_with('-') {
            paths.push(PathBuf::from(arg));
        }
    }

    for path in &paths {
        let resolved_path = if env::var_os("_ZO_RESOLVE_SYMLINKS").is_some() {
            fs::canonicalize(path).unwrap_or_else(|_| path.clone())
        } else {
            path.clone()
        };

        let score = score.unwrap_or(1);

        if let Some(existing) = entries.iter().position(|(p, _)| p == &resolved_path) {
            entries[existing].1 += score;
        } else {
            entries.push((resolved_path, score));
        }
    }

    if let Err(e) = write_db(&entries) {
        eprintln!("zoxide: failed to write database: {}", e);
        process::exit(1);
    }
}

fn run_edit() {
    let db_path = get_db_path();

    if !db_path.exists() {
        eprintln!("zoxide: database not found");
        process::exit(1);
    }

    let file = match File::open(&db_path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("zoxide: failed to open database: {}", e);
            process::exit(1);
        }
    };

    let reader = BufReader::new(file);
    let lines: Vec<String> = reader.lines().filter_map(|l| l.ok()).collect();

    if lines.is_empty() {
        eprintln!("zoxide: database is empty");
        process::exit(1);
    }

    let mut content = String::new();
    for line in &lines {
        content.push_str(line);
        content.push('\n');
    }

    let mut child = match process::Command::new("nano").arg("-").stdin(process::stdin()).stdout(process::stdout()).stderr(process::stderr()).spawn() {
        Ok(c) => c,
        Err(_) => {
            eprintln!("zoxide: failed to start editor");
            process::exit(1);
        }
    };

    let status = child.wait().unwrap();
    if !status.success() {
        process::exit(status.code().unwrap_or(1));
    }

    let new_content = child.stdout.unwrap();
    let new_lines: Vec<&str> = new_content.split('\n').collect();

    let mut new_entries = Vec::new();
    for line in new_lines {
        if line.is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() >= 2 {
            if let Ok(score) = parts[1].parse::<u64>() {
                new_entries.push((PathBuf::from(parts[0]), score));
            }
        }
    }

    if let Err(e) = write_db(&new_entries) {
        eprintln!("zoxide: failed to write database: {}", e);
        process::exit(1);
    }
}

fn run_import(args: &[String]) {
    let mut from = None;
    let mut path = None;
    let mut merge = false;

    for arg in args {
        if arg == "--from" {
            if args.len() > args.iter().position(|&x| x == "--from").unwrap() + 1 {
                from = Some(args[args.iter().position(|&x| x == "--from").unwrap() + 1].clone());
            }
        } else if arg == "--merge" {
            merge = true;
        } else if !arg.starts_with('-') {
            path = Some(PathBuf::from(arg));
        }
    }

    let from = match from {
        Some(f) => f,
        None => {
            eprintln!("zoxide: --from is required");
            process::exit(1);
        }
    };

    let path = match path {
        Some(p) => p,
        None => {
            eprintln!("zoxide: path is required");
            process::exit(1);
        }
    };

    if !path.exists() {
        eprintln!("zoxide: could not open database for importing: {}", path.display());
        eprintln!("\nCaused by:\n    No such file or directory (os error 2)");
        process::exit(1);
    }

    let mut entries = read_db();

    let db_file = match File::open(&path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("zoxide: could not open database for importing: {}", e);
            process::exit(1);
        }
    };

    let reader = BufReader::new(db_file);
    for line in reader.lines().filter_map(|l| l.ok()) {
        if line.is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() >= 2 {
            let p = PathBuf::from(parts[0]);
            let s: u64 = match parts[1].parse() {
                Ok(s) => s,
                Err(_) => continue,
            };

            if merge {
                if let Some(existing) = entries.iter().position(|(p, _)| p == &p) {
                    entries[existing].1 += s;
                } else {
                    entries.push((p, s));
                }
            } else {
                entries.push((p, s));
            }
        }
    }

    if let Err(e) = write_db(&entries) {
        eprintln!("zoxide: failed to write database: {}", e);
        process::exit(1);
    }
}

fn run_init(args: &[String]) {
    let mut shell = None;
    let mut no_cmd = false;
    let mut cmd = "z".to_string();
    let mut hook = "pwd".to_string();

    for arg in args {
        if arg == "--no-cmd" {
            no_cmd = true;
        } else if arg == "--cmd" {
            if args.len() > args.iter().position(|&x| x == "--cmd").unwrap() + 1 {
                cmd = args[args.iter().position(|&x| x == "--cmd").unwrap() + 1].clone();
            }
        } else if arg == "--hook" {
            if args.len() > args.iter().position(|&x| x == "--hook").unwrap() + 1 {
                hook = args[args.iter().position(|&x| x == "--hook").unwrap() + 1].clone();
            }
        } else if !arg.starts_with('-') {
            shell = Some(arg);
        }
    }

    let shell = match shell {
        Some(s) => s,
        None => {
            eprintln!("zoxide: shell is required");
            process::exit(1);
        }
    };

    let shell_lower = shell.to_lowercase();

    let output = match shell_lower.as_str() {
        "bash" => generate_bash(&no_cmd, &cmd, &hook),
        "zsh" => generate_zsh(&no_cmd, &cmd, &hook),
        "fish" => generate_fish(&no_cmd, &cmd, &hook),
        "elvish" => generate_elvish(&no_cmd, &cmd, &hook),
        "nushell" => generate_nushell(&no_cmd, &cmd, &hook),
        "posix" => generate_posix(&no_cmd, &cmd, &hook),
        "tcsh" => generate_tcsh(&no_cmd, &cmd, &hook),
        "xonsh" => generate_xonsh(&no_cmd, &cmd, &hook),
        "powershell" => generate_powershell(&no_cmd, &cmd, &hook),
        _ => {
            eprintln!("zoxide: unsupported shell: {}", shell);
            process::exit(1);
        }
    };

    print!("{}", output);
}

fn generate_bash(no_cmd: bool, cmd: &str, hook: &str) -> String {
    let hook_code = if hook == "pwd" {
        r#"
# Hook to add new entries to the database.
__zoxide_oldpwd="$(__zoxide_pwd)"

function __zoxide_hook() {
    builtin local -r retval="$?"
    builtin local pwd_tmp
    pwd_tmp="$(__zoxide_pwd)"
    if [[ ${__zoxide_oldpwd} != "${pwd_tmp}" ]]; then
        __zoxide_oldpwd="${pwd_tmp}"
        command zoxide add -- "${__zoxide_oldpwd}"
    fi
    return "${retval}"
}"#
    } else if hook == "none" {
        ""
    } else {
        r#"
# Hook to add new entries to the database.
__zoxide_oldpwd="$(__zoxide_pwd)"

function __zoxide_hook() {
    builtin local -r retval="$?"
    builtin local pwd_tmp
    pwd_tmp="$(__zoxide_pwd)"
    if [[ ${__zoxide_oldpwd} != "${pwd_tmp}" ]]; then
        __zoxide_oldpwd="${pwd_tmp}"
        command zoxide add -- "${__zoxide_oldpwd}"
    fi
    return "${retval}"
}"#
    };

    let init_code = if hook == "prompt" {
        r#"
# Initialize hook.
if [[ "${PROMPT_COMMAND:=}" != *'__zoxide_hook'* ]]; then
    if [[ "$(declare -p PROMPT_COMMAND 2>&1)" == "declare -a"* ]]; then
        PROMPT_COMMAND=("${PROMPT_COMMAND[@]}" __zoxide_hook)
    else
        # shellcheck disable=SC2128,SC2178
        PROMPT_COMMAND="${PROMPT_COMMAND%"${PROMPT_COMMAND##*[![:space:];]}"}"
        # shellcheck disable=SC2128,SC2178
        PROMPT_COMMAND="${PROMPT_COMMAND:+${PROMPT_COMMAND};}__zoxide_hook"
    fi
fi"#
    } else {
        ""
    };

    let z_complete = if !no_cmd {
        r#"
# Completions.
if [[ ${BASH_VERSINFO[0]:-0} -eq 4 && ${BASH_VERSINFO[1]:-0} -ge 4 || ${BASH_VERSINFO[0]:-0} -ge 5 ]] &&
    [[ ":${SHELLOPTS}:" =~ :(vi|emacs): && ${TERM} != 'dumb' ]]; then

    function __zoxide_z_complete_helper() {
        READLINE_LINE="z ${__zoxide_result@Q}"
        READLINE_POINT=${#READLINE_LINE}
        bind '"\e[0n": accept-line'
        builtin printf '\e[5n' > /dev/tty
    }

    function __zoxide_z_complete() {
        # Only show completions when the cursor is at the end of the line.
        [[ ${#COMP_WORDS[@]} -eq $((COMP_CWORD + 1)) ]] || return

        # If there is only one argument, use `cd` completions.
        if [[ ${#COMP_WORDS[@]} -eq 2 ]]; then
            builtin mapfile -t COMPREPLY < <(
                builtin compgen -A directory -- "${COMP_WORDS[-1]}" || builtin true
            )
