function __zoxide_zi() {{
    builtin local -r pwd_tmp="$(__zoxide_pwd)"
    builtin local -r result="$(command zoxide query --exclude "$pwd_tmp" --interactive)"
    if [[ -n "$result" ]]; then
        builtin cd "$result"
    fi
