+fn generate_fish(no_cmd: bool, hook: &str) -> String {
+    let z_func = if !no_cmd {
+        r#"
+# Jump to a directory using only keywords.
+function __zoxide_z
+    set -l args $argv
+    set -l pwd_tmp (__zoxide_pwd)
+    
+    if test (count $args) -eq 0; then
+        builtin cd ~
+    elif test (count $args) -eq 1 and "$args[1]" = "-"; then
+        builtin cd -
+    elif test (count $args) -eq 1 and -d "$args[1]"; then
+        builtin cd "$args[1]"
+    else
+        set -l result (__zoxide query --exclude "$pwd_tmp" -- $args)
+        if test -n "$result"; then
+            builtin cd "$result"
+        end
+    end
+end
+
+# Hook to add new entries to the database.
+__zoxide_oldpwd=__zoxide_pwd
+__zoxide_hook() {
+    set -l retval $status
+    set -l pwd_tmp (__zoxide_pwd)
+    if test "$__zoxide_oldpwd" != "$pwd_tmp"; then
+        set __zoxide_oldpwd "$pwd_tmp"
+        command zoxide add -- "$pwd_tmp"
+    end
+    return $retval
+}
